/**
 * LinkedIn job-alert digest parser
 * Expects: Company · Location line under title; one /jobs/view/{id}/ link per job
 * bucket_selected: systems | mechanical | controls (config title references, similarity)
 */

const BUCKET_THRESHOLD = 0.25;
const DEFAULT_BUCKET = 'systems';

function unique(arr) {
  return [...new Set(arr.filter(Boolean))];
}

function cleanText(s) {
  return String(s || '')
    .replace(/&middot;/gi, ' · ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, '\n')
    .replace(/&middot;/gi, ' · ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\n{2,}/g, '\n')
    .trim();
}

function getConfigValue(rows, key) {
  const wanted = cleanText(key).toLowerCase();
  const row = rows.find((item) => cleanText(item.json?.key).toLowerCase() === wanted);
  return cleanText(row?.json?.value || '');
}

function splitTerms(value) {
  return cleanText(value)
    .split(/[,;|\n]/)
    .map((term) => cleanText(term))
    .filter(Boolean);
}

function tokenize(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .filter((word) => word.length >= 3);
}

function jaccardSimilarity(a, b) {
  const aTokens = new Set(tokenize(a));
  const bTokens = new Set(tokenize(b));

  if (!aTokens.size || !bTokens.size) return 0;

  let intersection = 0;
  for (const token of aTokens) {
    if (bTokens.has(token)) intersection += 1;
  }

  const union = new Set([...aTokens, ...bTokens]).size;
  return intersection / union;
}

function titleSimilarity(title, reference) {
  const titleText = cleanText(title).toLowerCase();
  const referenceText = cleanText(reference).toLowerCase();

  if (!titleText || !referenceText) return 0;
  if (titleText.includes(referenceText) || referenceText.includes(titleText)) return 1;

  return jaccardSimilarity(titleText, referenceText);
}

function getBestMatch(title, terms) {
  let bestTerm = '';
  let bestScore = 0;

  for (const term of terms) {
    const score = titleSimilarity(title, term);
    if (score > bestScore) {
      bestScore = score;
      bestTerm = term;
    }
  }

  return { term: bestTerm, score: bestScore };
}

function getBucket(title, buckets) {
  let bestBucket = '';
  let bestScore = 0;

  for (const bucket of buckets) {
    const best = getBestMatch(title, bucket.terms);
    if (best.score > bestScore) {
      bestScore = best.score;
      bestBucket = bucket.name;
    }
  }

  if (bestScore >= BUCKET_THRESHOLD) return bestBucket;
  return DEFAULT_BUCKET;
}

let configRows = [];
try {
  configRows = $('Read config tab').all();
} catch (error) {
  configRows = [];
}

const buckets = [
  {
    name: 'systems',
    terms: splitTerms(getConfigValue(configRows, 'systems_title_references')),
  },
  {
    name: 'mechanical',
    terms: splitTerms(getConfigValue(configRows, 'mechanical_title_references')),
  },
  {
    name: 'controls',
    terms: splitTerms(getConfigValue(configRows, 'controls_title_references')),
  },
];

function extractJobLinks(raw) {
  const links = [];
  const re = /https:\/\/www\.linkedin\.com\/comm\/jobs\/view\/(\d+)[^\s)"']*/gi;
  let m;

  while ((m = re.exec(raw || '')) !== null) {
    const jobId = m[1];
    const url = m[0].replace(/[.,;]+$/, '');
    links.push({ jobId, url });
  }

  const byId = new Map();
  for (const link of links) {
    if (!byId.has(link.jobId)) byId.set(link.jobId, link.url);
  }

  return [...byId.entries()].map(([jobId, url]) => ({ jobId, url }));
}

function isNoiseLine(s) {
  const t = cleanText(s).toLowerCase();
  if (!t) return true;

  return (
    t === 'linkedin' ||
    t.startsWith('your job alert') ||
    t.startsWith('job alert:') ||
    t.startsWith('new jobs in') ||
    t.startsWith('manage your job alerts') ||
    t.startsWith('manage alerts') ||
    t.startsWith('view all jobs') ||
    t.startsWith('see all jobs') ||
    t.startsWith('apply with') ||
    t.startsWith('your job listings') ||
    t.includes('company alumni') ||
    t.includes('school alumni') ||
    t.includes('linkedin.com/comm/jobs/alerts') ||
    t === 'easy apply' ||
    t === 'premium' ||
    t === 'fast growing' ||
    t === 'actively recruiting' ||
    /^\d+\s+company alumni$/.test(t) ||
    /^\$\d/.test(t) ||
    /^messaging icon|^mynetwork icon|^notifications icon/.test(t)
  );
}

function looksLikeTitle(line) {
  const t = cleanText(line);
  if (!t || t.length > 140 || isNoiseLine(t)) return false;
  if (/^job alert:/i.test(t)) return false;
  if (t.includes(' · ')) return false;

  return /engineer|developer|manager|analyst|specialist|scientist|architect|lead|principal|technician/i.test(t);
}

function looksLikeLocationTail(tail) {
  const t = cleanText(tail);
  if (!t) return false;

  if (/\b(on-?site|remote|hybrid)\b/i.test(t)) return true;
  if (/\b(united states|usa|u\.s\.)\b/i.test(t)) return true;
  if (/,\s*[A-Z]{2}\b/.test(t)) return true;
  if (/\b[A-Z][a-z]+,\s*[A-Z]{2}\b/.test(t)) return true;

  return false;
}

function parseCompanyLocationLine(line) {
  const raw = cleanText(line);
  if (!raw.includes(' · ')) return null;

  const parts = raw.split(' · ');
  if (parts.length < 2) return null;

  const company = cleanText(parts[0]);
  const location = cleanText(parts.slice(1).join(' · '));

  if (!company || !location || isNoiseLine(company)) return null;
  if (!looksLikeLocationTail(location)) return null;
  if (looksLikeTitle(company)) return null;

  return { company, location };
}

function parseJobsFromLines(lines, links) {
  const jobs = [];
  let linkIndex = 0;

  for (let i = 0; i < lines.length; i++) {
    const parsed = parseCompanyLocationLine(lines[i]);
    if (!parsed) continue;

    const title = cleanText(lines[i - 1] || '');
    if (!looksLikeTitle(title)) continue;

    const link = links[linkIndex];
    if (!link?.url) continue;

    jobs.push({
      title,
      company: parsed.company,
      location: parsed.location,
      discovery_url: link.url,
      apply_url: '',
      jobId: link.jobId,
      bucket_selected: getBucket(title, buckets),
    });

    linkIndex += 1;
  }

  return jobs;
}

function parseJobsFromHtml(html, links) {
  const jobs = [];
  if (!html || !links.length) return jobs;

  const cardRe =
    /<a[^>]+href="(https:\/\/www\.linkedin\.com\/comm\/jobs\/view\/(\d+)[^"]*)"[^>]*>([\s\S]*?)<\/a>/gi;

  let m;
  const seen = new Set();

  while ((m = cardRe.exec(html)) !== null) {
    const jobId = m[2];
    if (seen.has(jobId)) continue;
    seen.add(jobId);

    const url = m[1].replace(/&amp;/g, '&');
    const anchorText = cleanText(stripHtml(m[3]));
    const linkEntry = links.find((l) => l.jobId === jobId);
    const discovery_url = linkEntry?.url || url;

    let title = anchorText;
    if (!looksLikeTitle(title)) title = '';

    jobs.push({
      title,
      company: '',
      location: '',
      discovery_url,
      apply_url: '',
      jobId,
      bucket_selected: title ? getBucket(title, buckets) : DEFAULT_BUCKET,
    });
  }

  return jobs;
}

function mergeJobs(primary, secondary) {
  const byId = new Map();

  for (const job of [...primary, ...secondary]) {
    if (!job.discovery_url) continue;

    const existing = byId.get(job.jobId);
    if (!existing) {
      byId.set(job.jobId, job);
      continue;
    }

    byId.set(job.jobId, {
      ...existing,
      title: existing.title || job.title,
      company: existing.company || job.company,
      location: existing.location || job.location,
      discovery_url: existing.discovery_url || job.discovery_url,
      apply_url: '',
      jobId: job.jobId,
      bucket_selected: existing.bucket_selected || job.bucket_selected || DEFAULT_BUCKET,
    });
  }

  return [...byId.values()].filter((j) => j.title && j.company && j.discovery_url);
}

const out = [];

for (const item of $input.all()) {
  const html = item.json.html || item.json.textHtml || '';
  const textRaw = item.json.text || '';
  const textAsHtml = item.json.textAsHtml || '';

  const rawBlob = [html, textRaw, stripHtml(textAsHtml)].join('\n');
  const links = extractJobLinks(rawBlob);

  const text = stripHtml(html) || textRaw || stripHtml(textAsHtml);
  const lines = text.split('\n').map(cleanText).filter((line) => line && !isNoiseLine(line));

  const fromLines = parseJobsFromLines(lines, links);
  const fromHtml = parseJobsFromHtml(html, links);
  const jobs = mergeJobs(fromLines, fromHtml);

  for (const job of jobs) {
    out.push({
      json: {
        title: job.title,
        company: job.company,
        location: job.location || '',
        apply_url: '',
        discovery_url: job.discovery_url,
        bucket_selected: job.bucket_selected || DEFAULT_BUCKET,
        status: 'needs_jd',
        source: 'linkedin_email',
        needs_manual_jd: true,
      },
    });
  }
}

return out;

