    const best = getBestMatch(title, bucket.terms);
    if (best.score > bestScore) {
      bestScore = best.score;
      bestBucket = bucket.name;
    }
  }

  if (bestScore >= BUCKET_THRESHOLD) return bestBucket;
  return DEFAULT_BUCKET;
}

let configRows = [];
try {
  configRows = $('Read config tab').all();
} catch (error) {
  configRows = [];
}

const buckets = [
  {
    name: 'systems',
    terms: splitTerms(getConfigValue(configRows, 'systems_title_references')),
  },
  {
    name: 'mechanical',
    terms: splitTerms(getConfigValue(configRows, 'mechanical_title_references')),
  },
  {
    name: 'controls',
    terms: splitTerms(getConfigValue(configRows, 'controls_title_references')),
  },
];

function isDiceJobUrl(line) {
  return /^https:\/\/www\.dice\.com\/job-detail\//i.test(clean(line));
}

function isNoiseLine(line) {
  const t = clean(line).toLowerCase();

  return (
    !t ||
    t.includes('where tech connects') ||
    t === 'log in' ||
    t.startsWith('hi,') ||
    t.startsWith('new matches for') ||
    t.startsWith('manage your') ||
    t.startsWith('view all jobs') ||
    t.includes('linkedin') ||
    t.includes('twitter') ||
    t.includes('facebook') ||
    t.includes('youtube') ||
    t.includes('subscribed for job alerts') ||
    t.includes('dice knowledge center') ||
    t.includes('unsubscribe') ||
    t.includes('copyright') ||
    t.includes('terms & conditions')
  );
}

const out = [];

for (const item of $input.all()) {
  const text =
    item.json.text ||
    item.json.textPlain ||
    item.json.body ||
    item.json.snippet ||
    '';

  const lines = text
    .split('\n')
    .map(clean)
    .filter((line) => line && !isNoiseLine(line));

  for (let i = 0; i < lines.length; i++) {
    if (!isDiceJobUrl(lines[i])) continue;

    const title = clean(lines[i - 1] || '');
    const discovery_url = clean(lines[i]);
    const company = clean(lines[i + 1] || '');

    if (!title || !company || isDiceJobUrl(title) || isDiceJobUrl(company)) {
      continue;
    }

    out.push({
      json: {
        title,
        company,
        location: '',
        apply_url: '',
        discovery_url,
        bucket_selected: getBucket(title, buckets),
        status: 'needs_jd',
        source: 'dice_email',
        needs_manual_jd: true,
      },
    });
  }
}

return out;

/**
 * Indeed Gmail parser: one job per email
 * Output: title, company, discovery_url, bucket_selected, status, source
 */

const BUCKET_THRESHOLD = 0.25;
const DEFAULT_BUCKET = 'systems';

function clean(s) {
  return String(s || '')
    .replace(/[\u034f\u200b\u200c\u200d\u2060\ufeff]/g, '')
    .replace(/[<>]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function getConfigValue(rows, key) {
  const wanted = clean(key).toLowerCase();
  const row = rows.find((item) => clean(item.json?.key).toLowerCase() === wanted);
  return clean(row?.json?.value || '');
}

function splitTerms(value) {
  return clean(value)
    .split(/[,;|\n]/)
    .map((term) => clean(term))
    .filter(Boolean);
}

function tokenize(value) {
