function cleanCompany(s) {
  return clean(s)
    .replace(/\s+\d+(\.\d+)?\s*★?$/g, '')
    .trim();
}

function isUrl(line) {
  const t = clean(line);
  return /^https?:\/\//i.test(t) || /^\[https?:\/\//i.test(t);
}

function extractGlassdoorJobLinks(raw) {
  const text = String(raw || '').replace(/&amp;/g, '&');
  const matches = text.match(/https?:\/\/[^\s"'<>]+/gi) || [];

  return [...new Set(matches)]
    .filter((link) => /glassdoor\.com/i.test(link))
    .filter((link) => !/\.(png|jpg|jpeg|gif|webp)(\?|$)/i.test(link))
    .filter((link) => !/unsubscribe|privacy|settings|assets|media|brandRefresh|brand-views|pixel|logo/i.test(link))
    .filter((link) => /\/job-listing\/|\/partner\/jobListing/i.test(link))
    .map((link) => link.replace(/[),.;]+$/, ''));
}

function looksLikeLocation(line) {
  const t = clean(line);
  return /^[A-Za-z .'-]+,\s*[A-Z]{2}$/.test(t) || /^United States( of America)?$/i.test(t);
}

function looksLikeSalary(line) {
  return /\$\d+K?\s*-\s*\$\d+K?/i.test(clean(line));
}

function looksLikeAge(line) {
  return /^(just posted|\d+[hd]|today|yesterday)$/i.test(clean(line));
}

function isNoise(line) {
  const t = clean(line).toLowerCase();

  return (
    !t ||
    t === 'glassdoor' ||
    t === 'avatar' ||
    t === 'easy apply' ||
    t.startsWith('job alert:') ||
    t.startsWith('check out your newest') ||
    t.startsWith('your job listings') ||
    t.startsWith('want more listings') ||
    t.startsWith('similar jobs') ||
    t.startsWith('create job alerts') ||
    t.startsWith('looking for something') ||
    t.startsWith('you can edit') ||
    t.startsWith('this message was sent') ||
    t.startsWith('privacy policy') ||
    t.startsWith('manage settings') ||
    t.startsWith('unsubscribe') ||
    t.startsWith('copyright') ||
    isUrl(line)
  );
}

const out = [];

for (const item of $input.all()) {
