  },
];

function getSender(item) {
  return clean(
    item.json.from?.text ||
    item.json.from?.value?.[0]?.address ||
    item.json.headers?.from ||
    item.json.replyTo?.text ||
    ''
  ).toLowerCase();
}

function isHandshakeEmail(item) {
  return getSender(item).includes('handshake@notifications.joinhandshake.com');
}

function extractHandshakeUrl(raw) {
  const matches = String(raw || '')
    .replace(/&amp;/g, '&')
    .match(/https?:\/\/[^\s"'<>]+/gi) || [];

  return (
    matches.find(
      (link) =>
        /joinhandshake\.com/i.test(link) &&
