    if (!updatedAt || updatedAt < cutoff) continue;

    const title = clean(job.title || job.full_title || '');
    if (!title) {
      skip.title += 1;
      continue;
    }

    if (!matchesRole(title, uniqueTerms, keywordTerms)) {
      skip.role += 1;
      continue;
    }

    const timestamp = getWorkableTimestamp(job);
    if (!timestamp || timestamp < cutoff) {
      skip.date += 1;
      continue;
    }

    const location = getWorkableLocation(job);
    if (!locationMatchesAllowedCountries(location, allowedCountries)) {
      skip.location += 1;
      continue;
    }

    const shortcode = clean(job.shortcode || job.code);
    let fullJd = '';

    if (shortcode) {
      try {
        const detail = await fetchWorkableJobDetail.call(this, slug, shortcode);
