              full_jd: clean(error.message || error),
              status: 'fetch_error',
              source: 'workable',
              bucket_selected: '',
              score: '',
              rank_reason: '',
            },
          });
        }
      }
    }

    const bucketSelected = getBucket(title, buckets);
    const url = getWorkableJobUrl(job);

    emitted += 1;

    out.push({
      json: {
        title,
        company,
        location,
        apply_url: url,
        discovery_url: url,
        posted_at: getWorkablePostedAt(job),
        needs_manual_jd: !fullJd,
        full_jd: fullJd,
        status: fullJd ? 'ready' : 'needs_jd',
        source: 'workable',
        bucket_selected: bucketSelected,
        score: '',
        rank_reason: '',
      },
    });
  }

  if (DEBUG) {
    out.push({
      json: {
        title: `DEBUG Workable parsed: ${company}`,
        company,
        location: '',
        apply_url: '',
        discovery_url: apiUrl,
        posted_at: '',
        needs_manual_jd: true,
        full_jd: `emitted=${emitted}; skipped_title=${skip.title}; skipped_role=${skip.role}; skipped_date=${skip.date}; skipped_location=${skip.location}; detail_errors=${skip.detail}`,
        status: 'debug',
        source: 'workable',
        bucket_selected: '',
        score: '',
        rank_reason: '',
      },
    });
  }
}

return out;

