  const match = rawUrl.match(/^https?:\/\/(?:www\.)?jobs\.smartrecruiters\.com\/([^/?#]+)/i);
  return match ? decodeURIComponent(match[1]) : '';
}

function isSmartRecruitersRow(row) {
  const atsType = clean(row.ats_type).toLowerCase();
  const url = clean(row.career_page_url || row.endpoint).toLowerCase();

  return (
    atsType === 'smartrecruiters' ||
    atsType === 'smartrecruiter' ||
    url.includes('smartrecruiters.com')
  );
}

function getDateValue(job) {
