}

function extractPostingId(value) {
  const raw = clean(value);
  if (!raw) return '';

  const match = raw.match(/\/postings\/([^/?#]+)/i);
  if (match) return match[1];

  if (raw.startsWith('http')) return '';

  return raw;
}

function getJobId(job) {
  const candidates = [job.id, job.uuid, job.postingId, job.smartRecruitersId, job.ref];

  for (const candidate of candidates) {
