function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function decodeHtmlEntities(text) {
  let value = String(text || '');

  const entities = {
    '&nbsp;': ' ',
    '&amp;': '&',
    '&quot;': '"',
    '&#39;': "'",
    '&apos;': "'",
    '&lt;': '<',
    '&gt;': '>',
    '&mdash;': '-',
    '&ndash;': '-',
    '&rsquo;': "'",
    '&lsquo;': "'",
    '&rdquo;': '"',
    '&ldquo;': '"',
  };

  for (const [entity, replacement] of Object.entries(entities)) {
    value = value.replace(new RegExp(entity, 'gi'), replacement);
  }

  return value
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([a-f0-9]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)));
}

function stripHtmlTags(html) {
  let text = decodeHtmlEntities(String(html || ''));

  text = text
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');

  text = text.replace(/<br\s*\/?>/gi, '\n');
  text = text.replace(/<\/(h[1-6])>/gi, '\n\n');
  text = text.replace(/<h[1-6][^>]*>/gi, '\n\n');
  text = text.replace(/<\/(p|div|section|article|blockquote)>/gi, '\n');
  text = text.replace(/<\/li>/gi, '\n');
  text = text.replace(/<li[^>]*>/gi, '\n- ');
  text = text.replace(/<\/(ul|ol|tr)>/gi, '\n');

  const parts = text.split('<');
  const out = [parts[0] || ''];

  for (let i = 1; i < parts.length; i++) {
    const chunk = parts[i];
    const closeIdx = chunk.indexOf('>');
    out.push(closeIdx === -1 ? `<${chunk}` : chunk.slice(closeIdx + 1));
  }

  return out.join('');
}

function stripHtml(html) {
  let text = stripHtmlTags(html);
  text = decodeHtmlEntities(text);

  if (/<[a-z][\s\S]*?>/i.test(text)) {
    text = stripHtmlTags(text);
  }

  return text
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t\f\v]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function plainOrHtml(plainValue, htmlValue) {
  const plain = String(plainValue ?? '').trim();
  if (plain) return plain;

  return stripHtml(htmlValue || '');
}

function dedupeParagraphs(text) {
  const blocks = String(text || '').split(/\n{2,}/);
  const seen = new Set();
  const out = [];

  for (const block of blocks) {
    const trimmed = block.trim();
    if (!trimmed) continue;

    const key = clean(trimmed).toLowerCase();
    if (seen.has(key)) continue;

    seen.add(key);
    out.push(trimmed);
  }

  return out.join('\n\n');
}

function trimAtSecondAboutRole(text) {
  const marker = /about the role\s*:?/gi;
  let first = -1;
  let match;

  while ((match = marker.exec(text)) !== null) {
    if (first === -1) {
      first = match.index;
      continue;
    }

    return text.slice(0, match.index).trim();
  }

  return text;
}


function formatSalaryRange(job) {
  const min = job.salaryRange?.min ?? job.salaryMin;
  const max = job.salaryRange?.max ?? job.salaryMax;
  const currency = clean(job.salaryRange?.currency || job.salaryCurrency || 'USD');

  if (min == null && max == null) return '';

  if (min != null && max != null) {
    return `$${Number(min).toLocaleString('en-US')} - $${Number(max).toLocaleString('en-US')} ${currency}`;
  }

  if (min != null) return `$${Number(min).toLocaleString('en-US')} ${currency}`;
  return `$${Number(max).toLocaleString('en-US')} ${currency}`;
}

function getLeverListContent(list) {
  if (typeof list?.contentPlain === 'string' && list.contentPlain.trim()) {
    return list.contentPlain.trim();
  }

  if (typeof list?.content === 'string' && list.content.trim()) {
    return stripHtml(list.content);
  }

  if (Array.isArray(list?.content)) {
    return list.content
      .map((item) => {
        if (typeof item === 'string') return stripHtml(item);
        return stripHtml(item?.text || item?.content || '');
      })
      .filter(Boolean)
      .join('\n');
  }

  return '';
}

function getLeverDescription(job) {
  const fullPlain = String(job.fullDescriptionPlain || '').trim();
  if (fullPlain.length > 200) {
    return dedupeParagraphs(trimAtSecondAboutRole(fullPlain));
  }

  const parts = [];

  const opening = plainOrHtml(job.openingPlain, job.opening);
  const body = plainOrHtml(job.descriptionBodyPlain, job.descriptionBody);

  if (opening && body) {
    parts.push(opening, body);
  } else {
    const main = plainOrHtml(job.descriptionPlain, job.description);
    if (main) parts.push(main);
  }

  if (Array.isArray(job.lists)) {
    for (const list of job.lists) {
      const header = clean(list.text);
      const content = getLeverListContent(list);

      if (header && content) {
        parts.push(`${header}\n${content}`);
      } else if (content) {
        parts.push(content);
      }
    }
  }

  const salaryLine = formatSalaryRange(job);
  const salaryDesc = plainOrHtml(job.salaryDescriptionPlain, job.salaryDescription);
  const additional = plainOrHtml(job.additionalPlain, job.additional);

  if (salaryLine) parts.push(salaryLine);
  if (salaryDesc) parts.push(salaryDesc);
  if (additional) parts.push(additional);

  return dedupeParagraphs(trimAtSecondAboutRole(parts.join('\n\n')));
}

function isEnabled(value) {
  return value === true || value === 1 || ['true', '1', 'yes', 'y'].includes(clean(value).toLowerCase());
}

function getConfigValue(rows, key) {
  const row = rows.find((item) => clean(item.json.key).toLowerCase() === key);
  return clean(row?.json.value || '');
}

function splitTerms(value) {
  return clean(value)
    .split(/[,;|\n]/)
    .map((term) => clean(term).toLowerCase())
    .filter(Boolean);
}

function tokenize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .filter((word) => word.length >= 3);
}

function jaccardSimilarity(a, b) {
  const aTokens = new Set(tokenize(a));
  const bTokens = new Set(tokenize(b));

  if (!aTokens.size || !bTokens.size) return 0;

  let intersection = 0;
  for (const token of aTokens) {
    if (bTokens.has(token)) intersection += 1;
  }

  const union = new Set([...aTokens, ...bTokens]).size;
  return intersection / union;
}

function titleSimilarity(title, reference) {
  const titleText = clean(title).toLowerCase();
  const referenceText = clean(reference).toLowerCase();

  if (!titleText || !referenceText) return 0;
  if (titleText.includes(referenceText) || referenceText.includes(titleText)) return 1;

  return jaccardSimilarity(titleText, referenceText);
}

function getBestMatch(title, terms) {
  let bestTerm = '';
  let bestScore = 0;

  for (const term of terms) {
    const score = titleSimilarity(title, term);

    if (score > bestScore) {
      bestScore = score;
      bestTerm = term;
    }
  }

  return { term: bestTerm, score: bestScore };
}

function matchesRole(title, terms, keywordTerms) {
  if (!terms.length) return false;

  const titleText = clean(title).toLowerCase();
  const best = getBestMatch(title, terms);
  if (best.score >= TITLE_THRESHOLD) return true;

  if (terms.some((term) => {
    const t = clean(term).toLowerCase();
    if (!t) return false;
    if (t.length >= 3 && titleText.includes(t)) return true;
    return tokenize(t).some((word) => word.length >= 3 && titleText.includes(word));
  })) {
    return true;
  }

  const keywords = Array.isArray(keywordTerms) ? keywordTerms : [];
  if (/engineer/i.test(titleText) && keywords.some((term) => {
    const t = clean(term).toLowerCase();
    return t && (titleText.includes(t) || tokenize(t).some((word) => word.length >= 3 && titleText.includes(word)));
  })) {
    return true;
  }

  return false;
}

function getBucket(title, buckets) {
  let bestBucket = '';
  let bestScore = 0;

  for (const bucket of buckets) {
    const best = getBestMatch(title, bucket.terms);

    if (best.score > bestScore) {
      bestScore = best.score;
      bestBucket = bucket.name;
    }
  }

  return bestScore >= TITLE_THRESHOLD ? bestBucket : '';
}

function normalizeCountry(value) {
  const v = clean(value).toLowerCase();

  if (['usa', 'us', 'u.s.', 'united states', 'united states of america'].includes(v)) return 'usa';
  if (['uk', 'united kingdom', 'england', 'scotland', 'wales'].includes(v)) return 'uk';
  if (['canada', 'ca'].includes(v)) return 'canada';

  return v;
}

function getAllowedCountries(configRows) {
  return splitTerms(getConfigValue(configRows, 'allowed_countries'))
    .map(normalizeCountry)
    .filter(Boolean);
}

function locationMatchesAllowedCountries(location, allowedCountries) {
  if (!allowedCountries.length) return true;

  const raw = clean(location);
  const value = raw.toLowerCase();
  if (!value) return false;

  const usStates = /\b(AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|IA|ID|IL|IN|KS|KY|LA|MA|MD|ME|MI|MN|MO|MS|MT|NC|ND|NE|NH|NJ|NM|NV|NY|OH|OK|OR|PA|RI|SC|SD|TN|TX|UT|VA|VT|WA|WI|WV|WY|DC)\b/;

  function hasUsMarker(text) {
    const t = clean(text).toLowerCase();
    return (
      t.includes('united states') ||
      t.includes('usa') ||
      t.includes('u.s.') ||
      t.includes('united states of america') ||
      usStates.test(clean(text))
    );
  }

  const normalizedAllowed = allowedCountries.map((country) => clean(country).toLowerCase());
  const wantsUsa = normalizedAllowed.some((country) =>
    ['usa', 'us', 'u.s.', 'united states', 'united states of america'].includes(country)
  );

  const isRemoteLike = /\b(remote|hybrid|work from home|wfh|distributed)\b/i.test(value);
  if (isRemoteLike) {
    return wantsUsa ? hasUsMarker(raw) : normalizedAllowed.some((country) => value.includes(country));
  }

  if (wantsUsa && hasUsMarker(raw)) return true;

  if (normalizedAllowed.includes('uk')) {
    if (
      value.includes('united kingdom') ||
      value.includes('uk') ||
      value.includes('england') ||
      value.includes('scotland') ||
      value.includes('wales')
    ) {
      return true;
    }
  }

  if (normalizedAllowed.includes('canada')) {
    const canadaProvinces = /\b(ON|BC|QC|AB|MB|SK|NS|NB|NL|PE|YT|NT|NU)\b/;
    if (value.includes('canada') || canadaProvinces.test(raw)) return true;
  }

  return normalizedAllowed.some((country) => value.includes(country));
}

function deriveLeverSlug(row) {
