  const relativeMatch = lower.match(/(\d+)\s*(\+)?\s*(day|days|week|weeks|month|months)\s+ago/);
  if (relativeMatch) {
    const amount = Number(relativeMatch[1]);
    const unit = relativeMatch[3];
    const multiplier = unit.startsWith('week') ? 7 : unit.startsWith('month') ? 30 : 1;
    const timestamp = Date.now() - amount * multiplier * DAY_MS;
    return { timestamp, display: raw };
  }

  if (lower.includes('30+') || lower.includes('30 plus')) {
    return { timestamp: Date.now() - 30 * DAY_MS, display: raw };
  }

  return { timestamp: 0, display: raw };
}

