function formatLocation(value) {
  if (!value) return '';

  if (typeof value === 'string') return clean(value);

  if (Array.isArray(value)) {
    return value.map((item) => formatLocation(item)).filter(Boolean).join(', ');
  }

  if (typeof value === 'object') {
    const city = clean(value.city);
    const state = clean(value.state || value.province);
    const country = clean(value.country || value.addressCountry);

    return clean(
      value.name ||
      value.label ||
      [city, state, country].filter(Boolean).join(', ')
    );
  }

  return clean(value);
}

