  },
}));

/**
 * n8n Code node — Workflow B
 * Rank jobs — score 0-10, prompt from jd_score_prompt via Filter node
 */

const BUCKET = 'mechanical';
const RESUME_CONFIG_KEY = 'mechanical_resume_text';

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function cleanResume(value) {
  return String(value ?? '').trim();
}

function truncate(text, maxLen) {
  const value = clean(text);
  if (value.length <= maxLen) return value;
  return `${value.slice(0, maxLen)}…`;
}

function parseJsonObject(raw) {
  const text = clean(raw);
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch (error) {}
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try {
    return JSON.parse(match[0]);
  } catch (error) {
    return null;
  }
}

function buildPrompt(template, vars) {
  let prompt = template || '';
  for (const [key, value] of Object.entries(vars)) {
    prompt = prompt.split(`{{${key}}}`).join(String(value ?? ''));
  }
  return prompt;
}

function getRankingConfig() {
  return $getWorkflowStaticData('global').rankingConfig || {};
}

const cfg = getRankingConfig();
const jobs = $input.all();

if (!jobs.length) {
  return [];
}

const sample = jobs[0].json || {};
const apiKey = clean($env.OPENAI_API_KEY || cfg.openai_api_key);
const model = clean(sample._openai_model || cfg.openai_model) || 'gpt-4o-mini';
const resume = cleanResume(sample._pipeline_resume || cfg[RESUME_CONFIG_KEY]);
const promptTemplate =
  cleanResume(sample._pipeline_rank_prompt) ||
  cleanResume(cfg.jd_score_prompt) ||
  '';

if (!apiKey) {
  throw new Error('Missing OPENAI_API_KEY in n8n env or config tab.');
}

if (!resume) {
  throw new Error(`Missing resume for ${BUCKET}. Run Filter ${BUCKET} bucket first.`);
}

if (!promptTemplate) {
  throw new Error('Missing jd_score_prompt. Check config tab and Filter node.');
}

const out = [];

for (const item of jobs) {
  const job = { ...(item.json || {}) };
  const userPrompt = buildPrompt(promptTemplate, {
    bucket: BUCKET,
    title: clean(job.title),
    company: clean(job.company),
    location: clean(job.location),
    full_jd: truncate(job.full_jd || job.description || '', 12000) || '(no job description provided)',
    resume: truncate(resume, 12000),
  });

  let parsed = null;
  let rankError = '';

  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/chat/completions',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: {
        model,
        temperature: 0.2,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: 'Respond with JSON only.' },
          { role: 'user', content: userPrompt },
        ],
      },
      json: true,
      timeout: 120000,
    });
    parsed = parseJsonObject(response?.choices?.[0]?.message?.content || '');
  } catch (error) {
    rankError = clean(error.message || error);
  }

  let score = Number(parsed?.score);
  if (!Number.isFinite(score)) score = 0;
  if (score > 10) score = score / 10;
  score = Math.max(0, Math.min(10, Math.round(score * 10) / 10));

  out.push({
    json: {
      ...job,
      bucket_selected: BUCKET,
      score,
      rank_reason: clean(parsed?.rank_reason || rankError || 'No rank reason returned'),
      status: rankError ? 'score_error' : 'scored',
      ranked_at: new Date().toISOString(),
    },
  });
}

return out;

/**
 * n8n Code node — Workflow B
 * Sort by score descending (highest first).
 */

const rows = $input.all();

rows.sort((a, b) => {
  const scoreA = Number(a.json?.score) || 0;
  const scoreB = Number(b.json?.score) || 0;
  return scoreB - scoreA;
});

return rows.map((item, index) => ({
  json: {
    ...(item.json || {}),
    rank: index + 1,
  },
}));

/**
 * n8n Code node — Workflow B
 * Set BUCKET below to: systems | mechanical | controls
 */

const BUCKET = 'controls';

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function cleanResume(value) {
  return String(value ?? '').trim();
}

function getRankingConfig() {
  const staticData = $getWorkflowStaticData('global');
  return staticData.rankingConfig || {};
}

const resumeKeyByBucket = {
  systems: 'systems_resume_text',
  mechanical: 'mechanical_resume_text',
  controls: 'controls_resume_text',
};

function readConfigValueFromTab(configKey) {
  const wanted = clean(configKey).toLowerCase();
  try {
    for (const item of $('Read config tab B').all()) {
      const key = clean(String(item.json?.key || '')).toLowerCase();
      if (key !== wanted) continue;
      const raw = item.json?.value;
      if (raw !== undefined && raw !== null && String(raw).trim()) {
        return cleanResume(raw);
      }
    }
  } catch (error) {}

  return '';
}

function readResumeFromConfigTab(resumeKey) {
  return readConfigValueFromTab(resumeKey);
}

function getJdScorePrompt(cfg) {
  const fromStore = cleanResume(cfg.jd_score_prompt || '');
  if (fromStore) return fromStore;

  const fromSheet = readConfigValueFromTab('jd_score_prompt');
  if (fromSheet) {
    const staticData = $getWorkflowStaticData('global');
    if (!staticData.rankingConfig) staticData.rankingConfig = {};
    staticData.rankingConfig.jd_score_prompt = fromSheet;
    return fromSheet;
  }

  return '';
}

function getResumeForBucket(bucket) {
  const resumeKey = resumeKeyByBucket[bucket] || `${bucket}_resume_text`;
  const cfg = getRankingConfig();
  let resume = cleanResume(cfg[resumeKey]);

  if (!resume) {
    resume = readResumeFromConfigTab(resumeKey);
    if (resume) {
      const staticData = $getWorkflowStaticData('global');
      if (!staticData.rankingConfig) staticData.rankingConfig = {};
      staticData.rankingConfig[resumeKey] = resume;
    }
  }

  return { resumeKey, resume, cfg };
}

const bucketJobs = $input.all().filter((item) => {
  const selected = clean(item.json?.bucket_selected).toLowerCase();
  return selected === BUCKET;
});

if (!bucketJobs.length) {
  return [];
}

const { resumeKey, resume, cfg } = getResumeForBucket(BUCKET);

if (!resume) {
  const staticCfg = getRankingConfig();
  const found = Object.keys(staticCfg)
    .filter((key) => key.includes('resume'))
    .map((key) => `${key}=${staticCfg[key] ? 'set' : 'empty'}`)
    .join(', ');

  throw new Error(
    `Missing ${resumeKey} for ${BUCKET} pipeline. ` +
    `Resume fields in staticData: ${found || 'none'}. ` +
    'Run full workflow from Start (not this node alone).'
  );
}

const promptTemplate = getJdScorePrompt(cfg);

if (!promptTemplate) {
  throw new Error(
    'Missing jd_score_prompt in config tab. Add row: key=jd_score_prompt, value=<your prompt>.'
  );
}

return bucketJobs.map((item) => ({
  json: {
    ...(item.json || {}),
    _pipeline_bucket: BUCKET,
    _pipeline_resume: resume,
    _pipeline_rank_prompt: promptTemplate,
    _openai_model: clean(cfg.openai_model) || 'gpt-4o-mini',
  },
}));

